import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'7EgFgcD6NyeoMB8KW4Pp',titulo:'Perfume Carolina Herrera 212 VIP Black Eau de Parfum 200 ml masculino',listing:'MLB6880438906'},{id:'87Q6AMHZ8ZFd06OzATcs',titulo:'Patinete Dobrável Infantil Juvenil 2 Rodas 2fly Replay Kids',listing:'MLB4147979056'}];
test('triagem58 exige identidade e preserva operação e afiliados com idempotência',()=>{for(const r of rows){const p={...r,preco:'99,99',linkAfiliado:'https://meli.la/preservado',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{titulo:'Capa para '+r.titulo},{id:'outro'},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}});
test('perfume sinaliza ambiguidade sem trocar volume por suposição',()=>{const x=correctProductData(rows[0]);assert.match(x.titulo,/volume a confirmar/);assert.doesNotMatch(x.titulo,/100 ml|200 ml/);assert.match(x.comentario,/endereço, sozinho, não comprova/);assert.match(x.comentario,/Não escolhemos um dos volumes como confirmado/);assert.doesNotMatch(x.pros,/200|100|sensual|fixação|ideal|original/i);});
test('2Fly só recebe categoria pública brinquedos sem limite de idade ou carga inventado',()=>{const x=correctProductData(rows[1]);assert.equal(x.categoria,'brinquedos');assert.equal(x.titulo,rows[1].titulo);assert.match(x.comentario,/sem afirmar presença ou ausência de motor/);assert.match(x.comentario,/não comprova correspondência, certificação ou segurança/);assert.doesNotMatch(x.pros,/80|kg|anos|certificad|seguro|antiderrapante/i);});
test('Dell mantém variante e conteúdo sem edição específica',()=>{const p={id:'7evzZBujin11TlbT8hvm',titulo:'Notebook Dell Dc15-i51334u-a50 15.6 Fhd I5 8gb 512gb Win 11',comentario:'Resumo existente',comparison:{family:'notebook',features:[{label:'Memória RAM',value:'8 GB'}]}},x=correctProductData(p);for(const k of Object.keys(p))assert.deepEqual(x[k],p[k]);});
